function getWAData() {
  try {
    const input = $("WA Command").item.json;
    const data = input?.body?.data;

    // ------------------------------------------
    // VALIDASI: APAKAH INI REQUEST DARI WA?
    // ------------------------------------------

    if (data) {
      const text =
        data?.message?.conversation ||
        data?.message?.extendedTextMessage?.text ||
        "";

      const remoteJid =
        data?.key?.remoteJid ||
        "";

      // ------------------------------------------
      // IDENTIFIKASI SENDER
      // ------------------------------------------

      let sender = remoteJid;

      // Jika pesan berasal dari grup WhatsApp,
      // remoteJid adalah ID grup (@g.us).
      // Ambil nomor pengirim sebenarnya dari participantAlt.
      if (remoteJid.endsWith("@g.us")) {
        sender =
          data?.key?.participantAlt ||
          data?.key?.participant ||
          "";
      }

      return {
        isScheduler: false,

        pesanWA: text.trim(),

        pesanWALower: text.toLowerCase().trim(),

        // Siapa yang mengirim pesan
        sender: sender,

        // Chat tujuan untuk membalas
        // Bisa nomor pribadi atau ID grup
        targetNumber: remoteJid,
      };
    }

    // ------------------------------------------
    // SCHEDULER
    // ------------------------------------------

    return {
      isScheduler: true,

      pesanWA: "otomatis",

      pesanWALower: "otomatis",

      sender: "",

      targetNumber: "",
    };

  } catch (e) {

    // ------------------------------------------
    // FALLBACK
    // ------------------------------------------
    // Jika node WA tidak tersedia / error,
    // anggap workflow dijalankan oleh scheduler.
    // ------------------------------------------

    return {
      isScheduler: true,

      pesanWA: "otomatis",

      pesanWALower: "otomatis",

      sender: "",

      targetNumber: "",
    };
  }
}


